"use client"

import * as React from "react"
import { GlimmProvider, useGlimm } from "glimm/react"

function Skeleton({ width, height = 8, radius = 6 }: { width: string | number; height?: number; radius?: number }) {
  return <span aria-hidden="true" style={{ background: "#f1f1f2", borderRadius: radius, display: "block", height, width }} />
}

function CloseIcon() {
  return <svg aria-hidden="true" fill="currentColor" height="14" viewBox="0 0 24 24" width="14"><path d="M17.2197 5.71967C17.5126 5.42678 17.9873 5.42678 18.2802 5.71967C18.5731 6.01256 18.5731 6.48732 18.2802 6.78022L13.0605 11.9999L18.2802 17.2197C18.5731 17.5126 18.5731 17.9873 18.2802 18.2802C17.9873 18.5731 17.5126 18.5731 17.2197 18.2802L11.9999 13.0605L6.78022 18.2802C6.48732 18.5731 6.01256 18.5731 5.71967 18.2802C5.42678 17.9873 5.42678 17.5126 5.71967 17.2197L10.9394 11.9999L5.71967 6.78022C5.42678 6.48732 5.42678 6.01256 5.71967 5.71967C6.01256 5.42678 6.48732 5.42678 6.78022 5.71967L11.9999 10.9394L17.2197 5.71967Z" /></svg>
}

function WorkspaceShell() {
  return (
    <>
      <header style={{ alignItems: "center", background: "#fff", borderBottom: "1px solid #ececee", display: "flex", height: 52, justifyContent: "space-between", padding: "0 16px" }}>
        <div style={{ alignItems: "center", display: "flex", gap: 12 }}><Skeleton height={24} radius={7} width={24} /><Skeleton height={10} width={96} /></div>
        <div style={{ alignItems: "center", display: "flex", gap: 12 }}>
          <div style={{ display: "flex" }}>
            {["09", "08", "07", "05"].map((id, index) => <img alt="" key={id} src={`https://glimm.dev/playground/img-${id}.jpg`} style={{ border: "2px solid #fff", borderRadius: 999, boxShadow: `0 0 0 1.5px ${["#f29e38", "#8062d4", "#4da37d", "#d5a24e"][index]}`, height: 28, marginLeft: index ? -5 : 0, objectFit: "cover", width: 28 }} />)}
          </div>
          <Skeleton height={32} radius={8} width={72} />
        </div>
      </header>
      <aside style={{ background: "#fff", borderRight: "1px solid #ececee", bottom: 0, left: 0, padding: "14px 12px", position: "absolute", top: 52, width: "19%" }}>
        <Skeleton width={54} />
        <div style={{ display: "grid", gap: 16, marginTop: 16 }}>
          {[94, 112, 72, 132, 88, 104, 68, 116].map((width, index) => <div key={index} style={{ alignItems: "center", display: "flex", gap: 10 }}><Skeleton height={11} width={11} /><Skeleton width={width} /></div>)}
        </div>
      </aside>
      <aside style={{ background: "#fff", borderLeft: "1px solid #ececee", bottom: 0, padding: "14px 16px", position: "absolute", right: 0, top: 52, width: "20%" }}>
        <Skeleton width={62} />
        <div style={{ display: "grid", gap: 10, gridTemplateColumns: "1fr 1fr", marginTop: 16 }}>
          {Array.from({ length: 10 }, (_, index) => <div key={index} style={{ background: "#fafafa", borderRadius: 6, height: 32, padding: "10px 8px" }}><Skeleton width={`${55 + (index % 4) * 10}%`} /></div>)}
        </div>
      </aside>
      <section style={{ backgroundColor: "#fafafa", backgroundImage: "radial-gradient(#dedee1 1px, transparent 1px)", backgroundSize: "18px 18px", bottom: 0, left: "19%", overflow: "hidden", padding: "70px 11%", position: "absolute", right: "20%", top: 52 }}>
        <article style={{ background: "#fff", border: "1px solid #eeeef0", borderRadius: 5, boxShadow: "0 2px 4px rgba(0,0,0,.02)", minHeight: 530, padding: 28 }}>
          <Skeleton height={12} width={168} />
          <div style={{ display: "grid", gap: 10, marginTop: 18 }}><Skeleton width="92%" /><Skeleton width="88%" /><Skeleton width="54%" /></div>
          <div style={{ marginTop: 26 }}><Skeleton height={235} radius={10} width="100%" /></div>
          <div style={{ display: "flex", gap: 10, marginTop: 18 }}><Skeleton height={32} radius={7} width={94} /><Skeleton height={32} radius={7} width={78} /></div>
        </article>
      </section>
    </>
  )
}

function JoinPanel() {
  const [shown, setShown] = React.useState(false)
  const { sweep } = useGlimm()

  const replay = React.useCallback(() => {
    setShown(false)
    window.setTimeout(() => {
      sweep(() => setShown(true), { palette: "berry", direction: "rtl", sweepMs: 1000, outroMs: 180 })
    }, 120)
  }, [sweep])

  React.useEffect(() => {
    const timer = window.setTimeout(replay, 550)
    return () => window.clearTimeout(timer)
  }, [replay])

  return (
    <main style={{ background: "#fff", color: "#242529", fontFamily: "Inter, ui-sans-serif, system-ui, sans-serif", minHeight: "100vh", overflow: "hidden", position: "relative", width: "100%" }}>
      <WorkspaceShell />
      <button aria-label="Replay the join" onClick={replay} type="button" style={{ height: 1, left: 0, opacity: 0, overflow: "hidden", position: "absolute", top: 0, width: 1 }} />
      <section aria-hidden={!shown} role="status" style={{ opacity: shown ? 1 : 0, pointerEvents: shown ? "auto" : "none", position: "absolute", right: 12, top: 60, transform: shown ? "translateY(0) scale(1)" : "translateY(-8px) scale(.98)", transformOrigin: "top right", transition: "opacity 260ms ease, transform 320ms cubic-bezier(.23,1,.32,1)", width: "min(300px, calc(100% - 24px))", zIndex: 20 }}>
        <div style={{ background: "#fff", borderRadius: 16, boxShadow: "0 18px 42px rgba(0,0,0,.13), 0 0 0 1px rgba(0,0,0,.06)", padding: 16 }}>
          <div style={{ alignItems: "center", display: "flex", gap: 8, marginTop: -2 }}>
            <span style={{ color: "#858589", flex: 1, fontSize: 13, fontWeight: 450, letterSpacing: "-.08px", lineHeight: "18px" }}>Joined your team</span>
            <button aria-label="Dismiss" onClick={() => setShown(false)} type="button" style={{ alignItems: "center", background: "#f5f5f6", border: 0, borderRadius: 999, color: "#c6c6c8", display: "inline-flex", height: 24, justifyContent: "center", padding: 0, width: 24 }}><CloseIcon /></button>
          </div>
          <div style={{ alignItems: "center", display: "flex", gap: 12, marginTop: 13 }}>
            <div style={{ border: "1.5px solid #2e70ff", borderRadius: 999, flex: "none", height: 44, padding: 2, position: "relative", width: 44 }}>
              <div style={{ borderRadius: 999, height: "100%", overflow: "hidden", position: "relative", width: "100%" }}><img alt="" src="https://cdn.21st.dev/assets/mirror/82/829381eb32de52819aa86999717c40cb1e6a16b4a4feca0aadfc03d928ca2f0f.jpg" style={{ height: 72, left: -7, maxWidth: "none", position: "absolute", top: -25, width: 48 }} /></div>
              <span aria-hidden="true" style={{ background: "#53bd70", borderRadius: 999, bottom: -1, boxShadow: "0 0 0 2px #fff", height: 11, position: "absolute", right: -1, width: 11 }} />
            </div>
            <div style={{ minWidth: 0 }}><div style={{ color: "#242529", fontSize: 15, fontWeight: 450, letterSpacing: "-.08px", lineHeight: "20px" }}>Tom Becker</div><div style={{ color: "#525257", fontSize: 13, letterSpacing: "-.08px", lineHeight: "18px", marginTop: 2 }}>Product designer · Berlin</div></div>
          </div>
          <div style={{ display: "grid", gap: 8, marginTop: 16 }}><Skeleton width="100%" /><Skeleton width="94%" /><Skeleton width="58%" /></div>
          <div style={{ display: "grid", gap: 8, gridTemplateColumns: "1fr 1fr", marginTop: 16 }}>
            <button type="button" style={{ background: "#fff", border: 0, borderRadius: 999, boxShadow: "0 1px 2px rgba(0,0,0,.10), 0 0 0 1px rgba(0,0,0,.06)", color: "#242529", fontFamily: "inherit", fontSize: 13, fontWeight: 450, height: 34 }}>Follow</button>
            <button type="button" style={{ background: "#242529", border: 0, borderRadius: 999, color: "#fff", fontFamily: "inherit", fontSize: 13, fontWeight: 450, height: 34 }}>Say hi</button>
          </div>
        </div>
      </section>
    </main>
  )
}

function GlimmTeammateJoins() {
  return <GlimmProvider><JoinPanel /></GlimmProvider>
}

export { GlimmTeammateJoins }
export default GlimmTeammateJoins

